Lemma art_annB_eq : forall (Mo Mn : word -> option byte) b c u,
  HAJ.ann_shadow Mo b u c ->
  (forall j, 0 <= j < (c + 7) / 8 -> Mn (Z_to_bv 64 (HeapIfaceA.S b + j)) = Mo (Z_to_bv 64 (HeapIfaceA.S b + j))) -> 0 <= u <= c ->
